{
  "name": "WebM Scribe",
  "description": "A professional-grade transcription tool specifically designed for .webm audio files, powered by Google's Gemini 3 Flash model for lightning-fast and accurate results."
}

export enum AppStatus {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR',
}

export interface TranscriptionResult {
  text: string;
  timestamp: number;
}

export const GEMINI_MODEL = 'gemini-3-flash-preview';

export const ACCEPTED_MIME_TYPES = [
  'audio/webm',
  'video/webm'
];

export const MAX_FILE_SIZE_MB = 20; // Client-side check example, though API handles up to token limits

import { GoogleGenAI } from "@google/genai";
import { GEMINI_MODEL } from "../constants";

// Helper to convert File to Base64
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the Data-URI prefix (e.g. "data:audio/webm;base64,")
      const base64Data = result.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = (error) => reject(error);
  });
};

export const transcribeAudio = async (file: File): Promise<string> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      throw new Error("API Key is missing. Please check your environment configuration.");
    }

    const ai = new GoogleGenAI({ apiKey });
    const base64Data = await fileToBase64(file);

    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: file.type,
              data: base64Data
            }
          },
          {
            text: "Please provide a highly accurate, verbatim transcription of this audio file. If there are multiple speakers, label them as Speaker 1, Speaker 2, etc. Format the output with clear line breaks between speakers."
          }
        ]
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No transcription was generated.");
    }

    return text;

  } catch (error) {
    console.error("Transcription error:", error);
    throw error;
  }
};

import React from 'react';

