import { GoogleGenAI } from "@google/genai";
import { GEMINI_MODEL } from "../constants";

// Helper to convert File to Base64
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the Data-URI prefix (e.g. "data:audio/webm;base64,")
      const base64Data = result.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = (error) => reject(error);
  });
};

export const transcribeAudio = async (file: File): Promise<string> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      throw new Error("API Key is missing. Please check your environment configuration.");
    }

    const ai = new GoogleGenAI({ apiKey });
    const base64Data = await fileToBase64(file);

    // Sanitize MIME type: remove parameters like ";codecs=opus" which cause API errors
    let mimeType = file.type.split(';')[0].trim();

    // Fallback for missing or generic MIME types
    if (!mimeType || mimeType === 'application/octet-stream') {
        // Since we enforce webm in the UI, defaulting to video/webm is a safe bet 
        // for the container, even if it's audio-only.
        mimeType = 'video/webm';
    }

    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Data
            }
          },
          {
            text: "Please provide a highly accurate, verbatim transcription of this audio file. If there are multiple speakers, label them as Speaker 1, Speaker 2, etc. Format the output with clear line breaks between speakers."
          }
        ]
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No transcription was generated.");
    }

    return text;

  } catch (error) {
    console.error("Transcription error:", error);
    // Improve error message for the user if it's a known API error
    if (error instanceof Error && error.message.includes('400')) {
         throw new Error("The file data was rejected by the server. Please ensure it is a valid .webm file.");
    }
    throw error;
  }
};

import React, { useCallback, useState, useRef } from 'react';
